    /** Funções, tipos de circuito e tipos de equipamento genéricos para começar a documentar sem cadastro prévio. */
    private function seed(): void
    {
        $roles = [
            ['Switch', '2196f3'], ['Roteador', '3f51b5'], ['Firewall', 'f44336'], ['Servidor', '4caf50'], ['Patch panel', '9e9e9e'],
            ['Ponto de rede', '795548'], ['DIO', 'ff9800'], ['PDU', 'ffc107'], ['Quadro de energia', 'ff5722'], ['Nobreak', '8bc34a'],
            ['Access point', '00bcd4'], ['Modem/ONT', '673ab7'], ['Estação de trabalho', '607d8b'], ['Impressora', '9c27b0'], ['Organizador', 'cfd8dc'],
        ];
        foreach ($roles as [$name, $color]) {
            $this->addSql('INSERT INTO dcim_device_role (name, color, created_at, updated_at) VALUES (?, ?, now(), now())', [$name, $color]);
        }
        foreach (['Internet dedicada', 'Internet banda larga', 'MPLS', 'Ponto a ponto (L2)', 'Telefonia/SIP'] as $name) {
            $this->addSql('INSERT INTO circuit_type (name, created_at, updated_at) VALUES (?, now(), now())', [$name]);
        }
        $this->addSql("INSERT INTO manufacturer (name, normalized_name) VALUES ('Genérico', 'genérico') ON CONFLICT (normalized_name) DO NOTHING");

        $types = [
            // [modelo, função, U, profundidade total, portas: [tipo de porta, nome|prefixo, quantidade, tipo físico, extras]]
            ['Patch panel 24 portas Cat6', 'Patch panel', 1, false, [['panel', '', 24, '8p8c', '110-punch']]],
            ['Patch panel 48 portas Cat6', 'Patch panel', 2, false, [['panel', '', 48, '8p8c', '110-punch']]],
            ['Ponto de rede simples (RJ45)', 'Ponto de rede', 0, false, [['panel', '', 1, '8p8c', '110-punch']]],
            ['Ponto de rede duplo (RJ45)', 'Ponto de rede', 0, false, [['panel', '', 2, '8p8c', '110-punch']]],
            ['DIO 12 fibras LC', 'DIO', 1, false, [['trunk', 'Bandeja', 12, 'lc', 'splice']]],
            ['DIO 24 fibras LC', 'DIO', 1, false, [['trunk', 'Bandeja', 24, 'lc', 'splice']]],
            ['Switch 24 portas + 4 SFP+', 'Switch', 1, false, [['interface', '', 24, '1000base-t'], ['interface', 'SFP', 4, '10gbase-x-sfpp'],
                ['console', 'Console', 1, 'rj-45'], ['power_port', 'Fonte', 1, 'iec-60320-c14', 60]]],
            ['Switch 48 portas + 4 SFP+', 'Switch', 1, false, [['interface', '', 48, '1000base-t'], ['interface', 'SFP', 4, '10gbase-x-sfpp'],
                ['console', 'Console', 1, 'rj-45'], ['power_port', 'Fonte', 1, 'iec-60320-c14', 90]]],
            ['Régua/PDU 8 tomadas', 'PDU', 1, false, [['power_port', 'Entrada', 1, 'nbr-14136-20a', 2200], ['power_outlet', '', 8, 'nbr-14136-10a']]],
            ['Quadro de distribuição 12 disjuntores', 'Quadro de energia', 0, false, [['power_outlet', 'Disjuntor ', 12, 'hardwired']]],
            ['Estação de trabalho', 'Estação de trabalho', 0, false, [['interface', 'eth0', 1, '1000base-t'], ['power_port', 'Fonte', 1, 'nbr-14136-10a', 250]]],
            ['Access point', 'Access point', 0, false, [['interface', 'eth0', 1, '1000base-t']]],
            ['Organizador de cabos 1U', 'Organizador', 1, false, []],
        ];
        foreach ($types as [$model, $role, $u, $full, $ports]) {
            $this->addSql(
                "INSERT INTO dcim_device_type (manufacturer_id, default_role_id, model, u_height, is_full_depth, created_at, updated_at)
                 SELECT m.id, r.id, ?, ?, ?, now(), now() FROM manufacturer m, dcim_device_role r WHERE m.normalized_name = 'genérico' AND r.name = ?",
                [$model, $u, $full ? 'true' : 'false', $role],
            );
            $type = "(SELECT dt.id FROM dcim_device_type dt JOIN manufacturer m ON m.id = dt.manufacturer_id WHERE m.normalized_name = 'genérico' AND dt.model = ".$this->connection->quote($model).')';
            foreach ($ports as $p) {
                [$kind, $prefix, $count, $physical] = $p;
                $name = 1 === $count && '' !== $prefix ? $this->connection->quote($prefix) : $this->connection->quote($prefix).' || g::text';
                if ('panel' === $kind) {
                    // patch panel / tomada: porta traseira (punch-down) N ↔ porta frontal (RJ45) N
                    $this->addSql("INSERT INTO dcim_port_template (device_type_id, kind, name, type, positions) SELECT $type, 'rear', $name, ?, 1 FROM generate_series(1, $count) g", [$p[4]]);
                    $this->addSql("INSERT INTO dcim_port_template (device_type_id, kind, name, type, positions, rear_port_template_id, rear_position)
                        SELECT $type, 'front', $name, ?, 1, r.id, 1 FROM generate_series(1, $count) g
                        JOIN dcim_port_template r ON r.device_type_id = $type AND r.kind = 'rear' AND r.name = $name", [$physical]);
                } elseif ('trunk' === $kind) {
                    // DIO: uma bandeja traseira com N posições ↔ N conectores frontais
                    $this->addSql("INSERT INTO dcim_port_template (device_type_id, kind, name, type, positions) VALUES ($type, 'rear', ?, ?, $count)", [$prefix, $p[4]]);
                    $this->addSql("INSERT INTO dcim_port_template (device_type_id, kind, name, type, positions, rear_port_template_id, rear_position)
                        SELECT $type, 'front', g::text, ?, 1, r.id, g FROM generate_series(1, $count) g
                        JOIN dcim_port_template r ON r.device_type_id = $type AND r.kind = 'rear' AND r.name = ?", [$physical, $prefix]);
                } else {
                    $draw = $p[4] ?? null;
                    $this->addSql("INSERT INTO dcim_port_template (device_type_id, kind, name, type, positions, maximum_draw) SELECT $type, ?, $name, ?, 1, ? FROM generate_series(1, $count) g",
                        [$kind, $physical, $draw]);
                }
            }
        }
    }
